/*Bad Ending Theme (COMPLETE) by Two2Fall*/

// main functions
t*=1.015,
// t = (-t + 2323860), // Uncomment to make this song backwards
seqnote = x => t * 2 ** ((x) / 12),
parse = (x, s) => parseInt(x[(t >> s) % x.length], 36) - 20,
addharmony3 = (ch1, ch2, ch3) => (ch1 % 85) + (ch2 % 85) + (ch3 % 85),
